"use client";

import { useState } from "react";
import { Check } from "lucide-react";
import { VISUAL_STYLES, STYLE_GROUPS } from "@vidforge/shared";

const FILTERS = ["All", ...STYLE_GROUPS];

/** Visual style cards with thumbnails (generated by `npm run marketing:images`; gradient fallback until then). */
export default function StylePicker({ value, onChange, compact = false }: { value: string; onChange: (id: string) => void; compact?: boolean }) {
  const [f, setF] = useState("All");
  const items = VISUAL_STYLES.filter((s) => f === "All" || s.group === f);
  return (
    <div>
      <div className="flex gap-2 overflow-x-auto pb-2 [scrollbar-width:none]">{FILTERS.map((x) => <button key={x} type="button" onClick={() => setF(x)} className={`min-h-[36px] whitespace-nowrap rounded-lg px-3 text-[13px] ${f === x ? "bg-accent text-white" : "border border-line text-ink-2 hover:border-line-2"}`}>{x}</button>)}</div>
      <div className={`mt-3 grid grid-cols-2 gap-3 ${compact ? "md:grid-cols-3" : "md:grid-cols-3 xl:grid-cols-4"}`}>
        {items.map((s, i) => {
          const active = value === s.id || value.toLowerCase() === s.name.toLowerCase();
          return (
            <button key={s.id} type="button" onClick={() => onChange(s.id)} className={`group relative overflow-hidden rounded-xl border text-left transition ${active ? "border-accent shadow-[0_0_0_1px_rgba(108,76,255,.6),0_10px_30px_rgba(108,76,255,.25)]" : "border-line hover:border-line-2"}`}>
              <div className="relative aspect-[4/3] bg-panel-2" style={{ background: `linear-gradient(135deg, hsl(${(i * 37) % 360} 45% 22%), hsl(${(i * 37 + 50) % 360} 55% 12%))` }}>
                <img src={`/assets/y2ube/gen/style_${s.id}.jpg`} alt="" loading="lazy" className="absolute inset-0 h-full w-full object-cover transition group-hover:scale-105" onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }} />
                {active && <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-accent text-white"><Check size={14} /></span>}
                {s.textInImage && <span className="absolute left-2 top-2 rounded bg-black/60 px-1.5 py-0.5 text-[10px] text-white" title="Labels are drawn inside the picture">Aa</span>}
              </div>
              <div className="p-2.5"><div className="text-[14px] font-semibold">{s.name}</div><div className="line-clamp-2 text-[12px] leading-snug text-ink-3">{s.description}</div></div>
            </button>
          );
        })}
      </div>
    </div>
  );
}
